// ❌ OLD: Writing custom JavaScript to gather values from disjoint DOM inputs
// and serializing them into an explicit fetch payload.
async function submitOrder() {
  const quantity = document.getElementById('qty-input').value;
  const coupon = document.getElementById('coupon-code').value;
  const payment = document.querySelector('input[name="payment"]:checked')?.value;

  const payload = { quantity, coupon, payment, clientTime: Date.now() };
  await fetch('/api/checkout', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
}
